window.SC_QUOTES = [
{it:{t:"Una mente grata è una grande mente che alla fine attrae a sé grandi cose.",a:"Platone"},
 en:{t:"A grateful mind is a great mind which eventually attracts great things to itself.",a:"Plato"}},
{it:{t:"L'Abbondanza non è qualcosa che acquisisci, ma è qualcosa con cui sintonizzarti.",a:"Wayne Dyer"},
 en:{t:"Abundance is not something you acquire. It is something you tune into.",a:"Wayne Dyer"}},
{it:{t:"Colui che vuole veramente impegnarsi nella via del bene deve sapere che non potrà evitare gli attacchi del male. Il male ha il compito di detestarvi e combattervi e, se proseguite nella stessa direzione divina malgrado i suoi attacchi, avete la prova della vostra grande elevazione.",a:"Omraam Mikhaël Aïvanhov"},
 en:{t:"Whoever truly wishes to walk the path of goodness must know they cannot avoid the attacks of evil. If you continue in the same divine direction despite its attacks, you have proof of your great elevation.",a:"Omraam Mikhaël Aïvanhov"}},
{it:{t:"Quando inizi a comprendere davvero le persone, il giudizio svanisce. Ognuno porta dentro di sé battaglie invisibili, ferite nascoste e lezioni ancora in corso. Essere empatici significa vedere oltre i difetti, riconoscere l'anima che c'è dietro le maschere.",a:"Scuola ContattaTi"},
 en:{t:"When you truly begin to understand people, judgement vanishes. Everyone carries invisible battles, hidden wounds and lessons still in progress. Being empathetic means seeing beyond flaws, recognising the soul behind the masks.",a:"Scuola ContattaTi"}},
{it:{t:"Si racconta che Alessandro il Grande, prima della sua morte, fece tre richieste: che la sua bara fosse portata dai migliori medici, che i suoi tesori fossero sparsi lungo il cammino, e che le sue mani restassero fuori dalla bara. Siamo arrivati a mani vuote e ce ne andiamo a mani vuote.",a:"Leggenda di Alessandro il Grande"},
 en:{t:"It is said that Alexander the Great, before his death, made three requests: that his coffin be carried by the finest doctors, that his treasures be scattered along the path, and that his hands remain outside the coffin. We arrived empty-handed and we leave empty-handed.",a:"Legend of Alexander the Great"}},
{it:{t:"L'uomo è la specie più folle: venera un Dio invisibile e distrugge una Natura visibile. Senza rendersi conto che la Natura che sta distruggendo è quel Dio che sta venerando.",a:"Hubert Reeves"},
 en:{t:"Humankind is the most insane species: it worships an invisible God and destroys a visible Nature. Without realising that the Nature it is destroying is the God it is worshipping.",a:"Hubert Reeves"}},
{it:{t:"Abbiamo accumulato tante ferite e, se non ne siamo consapevoli, tutte le nostre azioni diventano reazioni a quelle ferite. Nella conoscenza di Sé c'è la fine del dolore e quindi l'inizio della saggezza.",a:"J. Krishnamurti"},
 en:{t:"We have accumulated so many wounds and, if we are not aware of them, all our actions become reactions to those wounds. In self-knowledge lies the end of suffering and therefore the beginning of wisdom.",a:"J. Krishnamurti"}},
{it:{t:"La religione è per chi dorme. La spiritualità è per chi è sveglio. La religione reprime tutto, ti rende falso. La spiritualità trascende tutto, ti rende vero. La spiritualità è Divina, senza regole. È causa dell'Unione.",a:"Enzo Palomba"},
 en:{t:"Religion is for those who sleep. Spirituality is for those who are awake. Religion represses everything, makes you false. Spirituality transcends everything, makes you true. Spirituality is Divine, without rules. It is the cause of Union.",a:"Enzo Palomba"}},
{it:{t:"La Ricchezza non è possesso, ma Presenza. L'Abbondanza non è quantità, ma Qualità dell'Essere. La Missione non è ruolo, ma Espressione dell'Anima in azione.",a:"Anna Carla Digregorio & Nicolaos Anifantis"},
 en:{t:"Wealth is not possession, but Presence. Abundance is not quantity, but Quality of Being. Mission is not a role, but the Expression of the Soul in action.",a:"Anna Carla Digregorio & Nicolaos Anifantis"}},
{it:{t:"Non si tratta di attrarre. Si tratta di ricordare chi siamo. E permettere all'oro interiore di emergere.",a:"Scuola ContattaTi"},
 en:{t:"It is not about attracting. It is about remembering who we are. And allowing the inner gold to emerge.",a:"Scuola ContattaTi"}},
{it:{t:"Dal Piombo all'Oro, dal Bruco alla Farfalla: l'alchimia è il potere innato dell'essere umano di trasformare sé stesso. Ogni ostacolo si trasforma in soglia, ogni ferita in portale, ogni talento in offerta.",a:"Dal libro Ricchezza, Abbondanza e Mission"},
 en:{t:"From Lead to Gold, from Caterpillar to Butterfly: alchemy is the innate power of the human being to transform oneself. Every obstacle becomes a threshold, every wound a portal, every talent an offering.",a:"From the book Wealth, Abundance and Mission"}},
{it:{t:"Esistono menti che si interrogano, che desiderano la verità del cuore, la cercano, si sforzano di risolvere i problemi generati dalla vita. Se un uomo ragiona e pensa bene, deve inevitabilmente ritornare a se stesso, ed incominciare dalla soluzione del problema di che cosa egli stesso sia.",a:"Georges Ivanovitch Gurdjieff"},
 en:{t:"There are minds that question, that desire the truth of the heart, seek it, strive to solve the problems generated by life. If a man reasons and thinks well, he must inevitably return to himself and begin by solving the problem of what he himself is.",a:"Georges Ivanovitch Gurdjieff"}},
{it:{t:"La vita di ogni uomo è una via verso sé stesso. Quando odiamo qualcuno, odiamo nella sua immagine qualche cosa che sta dentro di noi. Ciò che non è in noi non ci mette agitazione.",a:"Hermann Hesse"},
 en:{t:"Every man's life is a way toward himself. When we hate someone, we hate something in their image that lies within us. What is not in us does not disturb us.",a:"Hermann Hesse"}},
{it:{t:"Tu sei già ciò che vuoi realizzare. Il fine della tua aspirazione esiste già, presente in te. Qui e ora, in questo preciso istante, tu sei ciò che è noto come divino.",a:"Osho"},
 en:{t:"You are already what you wish to realise. The aim of your aspiration already exists, present within you. Here and now, at this very moment, you are what is known as divine.",a:"Osho"}},
{it:{t:"La felicità è un affiorare interiore; è un risveglio delle tue energie; è un risveglio della tua anima.",a:"Osho"},
 en:{t:"Happiness is an inner blossoming; it is an awakening of your energies; it is an awakening of your soul.",a:"Osho"}},
{it:{t:"La vita inizia dove finisce la paura.",a:"Osho"},
 en:{t:"Life begins where fear ends.",a:"Osho"}},
{it:{t:"Chi guarda sé stesso rischia di incontrare sé stesso. Lo specchio non lusinga, mostra diligentemente quella faccia che non mostriamo mai al mondo perché la nascondiamo dietro la maschera dell'attore.",a:"Carl Gustav Jung"},
 en:{t:"Whoever looks at himself risks encountering himself. The mirror does not flatter, it diligently shows that face we never show the world because we hide it behind the actor's mask.",a:"Carl Gustav Jung"}},
{it:{t:"Atto d'amore è accogliere in noi la nostra parte più ferita e fragile. Arriva il momento in cui ci accorgiamo che l'ultimo degli uomini siamo noi.",a:"Carl Gustav Jung"},
 en:{t:"An act of love is to welcome within us our most wounded and fragile part. There comes a moment when we realise that the last of men is ourselves.",a:"Carl Gustav Jung"}},
{it:{t:"Colui che cerca non desista dal cercare fino a quando non avrà trovato; quando avrà trovato si stupirà. Quando si sarà stupito, si turberà e dominerà su tutto.",a:"Vangelo di Tommaso"},
 en:{t:"Let the seeker not cease from seeking until they find; when they find they shall be astonished. When astonished, they shall be troubled and shall rule over all.",a:"Gospel of Thomas"}},
{it:{t:"Racchiudi la Verità nel tuo Cuore, e che essa parli attraverso le tue Opere. La Scienza sarà la tua forza; la Fede la tua spada; e il Silenzio la tua corazza impenetrabile.",a:"Ermete Trismegisto"},
 en:{t:"Enclose the Truth in your Heart, and let it speak through your Works. Science shall be your strength; Faith your sword; and Silence your impenetrable armour.",a:"Hermes Trismegistus"}},
{it:{t:"L'Albero della Vita affonda le sue radici nel tuo stesso cuore.",a:"Gialad-ad-din Rumì"},
 en:{t:"The Tree of Life sinks its roots into your very heart.",a:"Jalāl ad-Dīn Rūmī"}},
{it:{t:"Se potessimo vedere il miracolo di un singolo fiore, la nostra intera vita cambierebbe.",a:"Buddha"},
 en:{t:"If we could see the miracle of a single flower, our entire life would change.",a:"Buddha"}},
{it:{t:"Ogni essere è una scintilla del divino. Tu non sei separato dalla globalità. Sei una cosa sola con il sole, la terra, l'aria. Tu non hai una vita. Tu sei la vita.",a:"Eckhart Tolle"},
 en:{t:"Every being is a spark of the divine. You are not separate from the whole. You are one with the sun, the earth, the air. You do not have a life. You are life.",a:"Eckhart Tolle"}},
{it:{t:"Non sottovalutare mai il potere di credere in qualcosa che ancora non esiste. A volte il mondo ha solo bisogno che tu sia il primo a vederlo.",a:"Jim Carrey"},
 en:{t:"Never underestimate the power of believing in something that does not yet exist. Sometimes the world just needs you to be the first to see it.",a:"Jim Carrey"}},
{it:{t:"L'unico modo in cui l'uomo può contribuire alla costruzione di questa forma gloriosa è quello di coltivare un AMORE PURO, altruistico, benefico, universale. Amore puro diede origine all'universo, amore puro lo sostiene, amore puro lo spinge verso la perfezione.",a:"Sapienza Antica"},
 en:{t:"The only way man can contribute to the building of this glorious form is to cultivate a PURE, selfless, beneficent, universal LOVE. Pure love gave birth to the universe, pure love sustains it, pure love drives it toward perfection.",a:"Ancient Wisdom"}},
{it:{t:"Quando l'ignoranza urla, l'intelligenza tace. La tua pace e tranquillità valgono di più.",a:"Scuola ContattaTi"},
 en:{t:"When ignorance shouts, intelligence remains silent. Your peace and tranquillity are worth more.",a:"Scuola ContattaTi"}},
{it:{t:"Se non state servendo uno scopo più elevato in maniera volontaria, allora non state vivendo, ma solo esistendo.",a:"Salvatore Brizzi"},
 en:{t:"If you are not serving a higher purpose voluntarily, then you are not living, merely existing.",a:"Salvatore Brizzi"}},
{it:{t:"Ogni difficoltà ed ogni sofferenza è una lezione di apprendimento dell'amore.",a:"Anna Carla Digregorio"},
 en:{t:"Every difficulty and every suffering is a lesson in learning love.",a:"Anna Carla Digregorio"}},
{it:{t:"Chi ha abbandonato l'ego non ha più cose che gli piacciono e cose che non gli piacciono: qualsiasi cosa gli si presenti, ne gioisce. Non pone più condizioni all'esistenza: vive incondizionatamente.",a:"Osho, La via della gioia"},
 en:{t:"Whoever has abandoned the ego no longer has things they like and things they dislike: whatever comes their way, they rejoice in it. They no longer place conditions on existence: they live unconditionally.",a:"Osho, The Way of Joy"}},
{it:{t:"Il mondo si fiderebbe più di un guru che lo convinca di essere illuminato, o preferirebbe che gli indicasse quanto è profondo il suo sonno? E tu che leggi, sei sicuro di riuscire a discernere ciò che ti piace da ciò che più ti serve?",a:"Fabio Pietro Iacontino, Intelligentia Solis"},
 en:{t:"Would the world trust a guru who convinces it of being enlightened, or would it prefer one who shows how deep its sleep is? And you who read, are you sure you can discern what pleases you from what serves you most?",a:"Fabio Pietro Iacontino, Intelligentia Solis"}},
{it:{t:"Non chiedersi perché ci è accaduto un certo evento è come usare le parole senza coglierne il significato, come se la parola 'amore' si esaurisse nel suono e non significasse qualcosa di concreto.",a:"Salvatore Brizzi"},
 en:{t:"Not asking ourselves why a certain event happened to us is like using words without grasping their meaning, as if the word 'love' were exhausted by its sound and did not signify something concrete.",a:"Salvatore Brizzi"}},
{it:{t:"È sempre il falso che ti fa soffrire: i falsi desideri, le false paure, i falsi valori e i falsi rapporti con la gente. Abbandona il falso e sarai libero dal dolore: la verità rende felici, la verità affranca.",a:"Nisargadatta Maharaj"},
 en:{t:"It is always the false that makes you suffer: false desires, false fears, false values and false relationships with people. Abandon the false and you shall be free from pain: truth makes happy, truth liberates.",a:"Nisargadatta Maharaj"}},
{it:{t:"Il senso del dovere senza amore rende imbronciati. La responsabilità senza amore rende implacabili. La giustizia senza amore rende duri. La saggezza senza amore rende fasulli. Il potere senza amore rende crudeli. La risposta è sempre l'amore.",a:"Lao Tzu"},
 en:{t:"Duty without love makes you sullen. Responsibility without love makes you relentless. Justice without love makes you hard. Wisdom without love makes you fake. Power without love makes you cruel. The answer is always love.",a:"Lao Tzu"}},
{it:{t:"Non imparerai mai nulla dalla vita se credi di avere sempre ragione.",a:"Keanu Reeves"},
 en:{t:"You will never learn anything from life if you think you are always right.",a:"Keanu Reeves"}},
{it:{t:"Quando siete malati cercate la guarigione, nel senso che volete tornare alla condizione precedente la malattia, ma quella condizione è stata la causa della malattia! Guarire significa invece diventare una persona nuova.",a:"Salvatore Brizzi"},
 en:{t:"When you are ill you seek healing, meaning you want to return to the condition before the illness, but that condition was the cause of the illness! To heal means to become a new person.",a:"Salvatore Brizzi"}},
{it:{t:"Se una cosa fa male, vuol dire che qualcosa dentro di te è stato represso. Invece di evitare il dolore, entraci dentro: così la ferita è totalmente esposta e comincia a guarire.",a:"Osho"},
 en:{t:"If something hurts, it means something within you has been repressed. Instead of avoiding the pain, go into it: so the wound is fully exposed and begins to heal.",a:"Osho"}},
{it:{t:"L'essere umano è situato al confine tra il mondo inferiore e il mondo superiore. Se si lascia assorbire dalle forze del mondo superiore, diventa un focolaio di correnti luminose. Ma deve mantenere l'equilibrio fra la terra e il Cielo: la sua missione è lavorare sulla terra con i mezzi del Cielo.",a:"Omraam Mikhaël Aïvanhov"},
 en:{t:"The human being stands on the boundary between the lower world and the higher world. If absorbed by the forces of the higher world, they become a beacon of luminous currents. But they must maintain the balance between earth and Heaven: their mission is to work on earth with the means of Heaven.",a:"Omraam Mikhaël Aïvanhov"}},
{it:{t:"La Strega insegnò al guerriero l'umiltà e il rispetto. Il Guerriero insegnò alla strega il valore e il coraggio. Insieme insegnarono al mondo l'Amore. Il mondo uccise la strega e rese schiavo il guerriero. Ma non poté impedire all'amore di fare rinascere la strega e liberare il guerriero.",a:"Tradizione orale"},
 en:{t:"The Witch taught the warrior humility and respect. The Warrior taught the witch valour and courage. Together they taught the world Love. The world killed the witch and enslaved the warrior. But it could not prevent love from rebirting the witch and freeing the warrior.",a:"Oral tradition"}},
{it:{t:"Se escludiamo il male facendo finta che non esista, non vivremmo mai una vita vera. Per vedere la bellezza bisogna svegliarsi, e per svegliarsi bisogna avere il coraggio di vedere le cose come stanno: questa è la cosa più difficile.",a:"Giovanni Berti"},
 en:{t:"If we exclude evil by pretending it does not exist, we would never live a true life. To see beauty one must awaken, and to awaken one must have the courage to see things as they are: this is the most difficult thing.",a:"Giovanni Berti"}},
{it:{t:"Impara a camminare sulla terra chi considera il cielo come vivente. Maestro è chi marcia sicuro sulla Terra. Non rinunciate alla vita terrena senza prima averla ben compresa. Quando l'ora scocca, anche una formica può essere un messaggero.",a:"Foglie del Giardino di Morya, Illuminazione 1925"},
 en:{t:"Those who consider heaven as living learn to walk upon the earth. A Master is one who walks confidently on Earth. Do not renounce earthly life without first having understood it. When the hour strikes, even an ant can be a messenger.",a:"Leaves of Morya's Garden, Illumination 1925"}},
{it:{t:"Consapevolezza e sofferenza sono inversamente proporzionali: se c'è una non c'è l'altra. La consapevolezza unita all'accettazione spalanca i cancelli all'amore. Sei cambiato al tuo interno e, di conseguenza, è cambiato il tuo destino.",a:"Roberto Potocniak"},
 en:{t:"Awareness and suffering are inversely proportional: where one exists, the other does not. Awareness united with acceptance flings open the gates of love. You have changed within, and consequently, your destiny has changed.",a:"Roberto Potocniak"}},
{it:{t:"Tutti credono si tratti dell'egoismo delle altre persone, non del loro. Ma l'unica persona al mondo che puoi cambiare è proprio quella dalla quale non ti separi mai. Quando il tuo Cuore si apre, realizzi che l'unico problema del mondo eri tu.",a:"Salvatore Brizzi"},
 en:{t:"Everyone believes it is about other people's selfishness, not their own. But the only person in the world you can change is the one you never part from. When your Heart opens, you realise the only problem in the world was you.",a:"Salvatore Brizzi"}},
{it:{t:"Non risolvi un incubo lavorando sull'incubo. L'incubo scompare svegliandosi dallo stato di sonno ipnotico nel quale si stava vivendo. Non lavorare sul sintomo, bensì sulla causa radice.",a:"Roberto Potocniak"},
 en:{t:"You do not solve a nightmare by working on the nightmare. The nightmare vanishes by waking up from the hypnotic sleep in which you were living. Do not work on the symptom, but on the root cause.",a:"Roberto Potocniak"}},
{it:{t:"Mantieni la tua anima forte e pulita e tutto andrà bene. Non credere di essere solo, né debole, perché dentro di te ci sono eserciti potenti che nemmeno puoi immaginare. Se elevi il tuo spirito, non c'è niente che possa toccarti. L'unico nemico che devi temere è te stesso.",a:"Paracelso"},
 en:{t:"Keep your soul strong and clean and all will be well. Do not believe yourself alone or weak, for within you are powerful armies you cannot even imagine. If you elevate your spirit, nothing can touch you. The only enemy you need fear is yourself.",a:"Paracelsus"}},
{it:{t:"Gesù non vede il cieco come colui che ha sbagliato, ma come colui che è pronto a manifestare una qualità divina alla massima potenza. Non giudicare dalle apparenze: ogni difficoltà può essere la sfida al massimo livello per il perfezionamento.",a:"Scuola ContattaTi"},
 en:{t:"Jesus does not see the blind man as one who has sinned, but as one ready to manifest a divine quality at full power. Do not judge by appearances: every difficulty may be the highest-level challenge for perfection.",a:"Scuola ContattaTi"}},
{it:{t:"Il desiderio di longevità è contro natura ed è satanico se non è giustificato dal desiderio di servire più a lungo assecondando la propria missione.",a:"Salvatore Brizzi"},
 en:{t:"The desire for longevity is against nature and is satanic if not justified by the desire to serve longer in accordance with one's mission.",a:"Salvatore Brizzi"}},
{it:{t:"I due passaggi iniziatici per essere pronti ad accedere ad una via oggettiva: 1. La completa disillusione verso il mondo. 2. La completa disillusione verso sé stessi, verso ciò che si crede di essere e di poter fare.",a:"Roberto Potocniak"},
 en:{t:"The two initiatic passages to be ready to access an objective way: 1. Complete disillusionment with the world. 2. Complete disillusionment with oneself, with what one believes oneself to be and to be capable of doing.",a:"Roberto Potocniak"}},
{it:{t:"Tu non puoi cambiare nessuno. Nella vita ci si innalza solo per propria scelta. Tu puoi solo portare avanti la tua Missione mostrando nelle parole e nei fatti un nuovo mondo possibile.",a:"Salvatore Brizzi"},
 en:{t:"You cannot change anyone. In life one rises only by one's own choice. You can only carry forward your Mission by showing, in words and deeds, a new possible world.",a:"Salvatore Brizzi"}},
{it:{t:"La disobbedienza richiede un'intelligenza di ordine leggermente superiore. La persona intelligente si chiederà prima o poi: perché? Così si diventa responsabili di sé.",a:"Osho"},
 en:{t:"Disobedience requires an intelligence of a slightly higher order. The intelligent person will sooner or later ask: why? Thus one becomes responsible for oneself.",a:"Osho"}},
{it:{t:"Diffidate delle grandi parole gridate in piazza; rifuggite l'amore generalista, non concreto. Il Vangelo non proclama ideologie… e in questo risiede la sua forza.",a:"Salvatore Brizzi"},
 en:{t:"Beware of grand words shouted in the square; flee generalised, non-concrete love. The Gospel proclaims no ideologies… and therein lies its strength.",a:"Salvatore Brizzi"}},
{it:{t:"Fuggire le false tranquillità, aprire gli occhi infinitamente, come è infinita la luce, è sempre un momento di fioritura di sé stessi.",a:"Daniel Meurois & Anne Givaudan"},
 en:{t:"To flee false tranquillities, to open one's eyes infinitely, as infinite is the light, is always a moment of flowering of oneself.",a:"Daniel Meurois & Anne Givaudan"}},
{it:{t:"L'amore è forza rivoluzionaria, poiché rovescia l'algida geometria del do ut des. È la cellula della comunità. Amare significa realizzarsi con l'altro, volendo che l'altro sia pienamente.",a:"Diego Fusaro"},
 en:{t:"Love is a revolutionary force, for it overturns the cold geometry of quid pro quo. It is the cell of community. To love means to realise oneself with the other, willing that the other be fully.",a:"Diego Fusaro"}},
{it:{t:"Non aver paura di fallire… Abbi paura di non averci provato… Abbi paura di non averne goduto nel farlo… Abbi paura di non amare abbastanza ciò che fai… Ma mai del fallimento…",a:"Anna Carla Digregorio"},
 en:{t:"Do not be afraid to fail… Be afraid of not having tried… Be afraid of not having enjoyed it… Be afraid of not loving what you do enough… But never of failure…",a:"Anna Carla Digregorio"}},
{it:{t:"Abbi Fede e lascia che sia… asseconda con Grazia il torrente dell'Esistenza… e potresti accorgerti che così la vita risulta anche divertente!",a:"Anna Carla Digregorio"},
 en:{t:"Have Faith and let it be… flow with Grace along the torrent of Existence… and you might notice that life turns out to be fun too!",a:"Anna Carla Digregorio"}},
{it:{t:"Fino a quando argomenti come Legge dello Specchio, giudizio e Legge di Compensazione non vi sono ben chiari, a cosa mai può servirvi purificare un chakra? Vi addormenterete ancora di più.",a:"Salvatore Brizzi"},
 en:{t:"Until topics like the Law of the Mirror, judgement and the Law of Compensation are truly clear to you, what good could purifying a chakra possibly do? You will only fall deeper asleep.",a:"Salvatore Brizzi"}},
{it:{t:"Spiritualità fast-food: credere che esistano rimedi facili e rapidi. La trasformazione spirituale non può essere rapida perché il processo stesso consiste nel lasciare la fretta e rispettare i propri ritmi naturali.",a:"Angy Scrò"},
 en:{t:"Fast-food spirituality: believing that easy and quick remedies exist. Spiritual transformation cannot be rapid because the process itself consists in leaving haste behind and respecting one's own natural rhythms.",a:"Angy Scrò"}},
{it:{t:"La Comunione di Coppia è di per sé un riflesso dell'Amore Divino. Comunione di Coppia che è il primo passo verso la Comunione con il Tutto.",a:"Anna Carla Digregorio & Nicolaos Anifantis"},
 en:{t:"The Communion of Couple is in itself a reflection of Divine Love. Communion of Couple that is the first step toward Communion with the All.",a:"Anna Carla Digregorio & Nicolaos Anifantis"}},
{it:{t:"Abbi Fede, la luce c'è certamente! È lì fuori che ti aspetta… Impegniamoci al massimo per forzare la porta e permetterci di vederla, quella Luce fino ad allora solo teorizzata.",a:"Anna Carla Digregorio"},
 en:{t:"Have Faith, the light is certainly there! It is out there waiting for you… Let us commit fully to forcing the door open and allowing ourselves to see it, that Light hitherto only theorised.",a:"Anna Carla Digregorio"}},
{it:{t:"Di Gesù non bisogna prenderci solo ciò che ci piace e che ci sembra convenire. Di Lui dobbiamo imparare a prendere anche tutto ciò che rigettiamo perché scardina le nostre convinzioni. Ma alla fine proprio lì si gioca il meglio della vita.",a:"Luigi Maria Epicoco"},
 en:{t:"Of Jesus we must not take only what we like and what seems to suit us. From Him we must also learn to take everything we reject because it upends our convictions. But in the end, that is precisely where the best of life is played.",a:"Luigi Maria Epicoco"}},
{it:{t:"L'amore è un fenomeno circolare: esce ed entra, amplificandosi sempre più. Più dai, più ricevi. Molti si lamentano di aver dato tanto senza ricevere niente: questo accade sempre quando si dà solo per ricevere… che non è dare, ma mendicare.",a:"Roberto Potocniak"},
 en:{t:"Love is a circular phenomenon: it goes out and comes in, ever amplifying. The more you give, the more you receive. Many complain of having given much without receiving anything: this always happens when one gives only to receive… which is not giving, but begging.",a:"Roberto Potocniak"}},
{it:{t:"Considerare la vita come una scuola meravigliosa, come una dura ma salutare palestra dove si temprano le più alte qualità e poteri umani e spirituali. Di fronte a ogni prova, invece delle abituali reazioni di abbattimento, dirsi: quale bene ne posso trarre?",a:"Roberto Assagioli"},
 en:{t:"Consider life as a wonderful school, as a tough but salutary gymnasium where the highest human and spiritual qualities and powers are tempered. Faced with every trial, instead of the usual reactions of dejection, tell yourself: what good can I draw from this?",a:"Roberto Assagioli"}},
{it:{t:"La bellezza ispira resistenza. Lo stato naturale dell'uomo è difendere le cose belle. Stanno attaccando la tua anima. Stanno uccidendo qualsiasi cosa possa ispirare la tua resistenza. È fatto di proposito. Diffidate.",a:"Salvatore Brizzi"},
 en:{t:"Beauty inspires resistance. The natural state of the human being is to defend beautiful things. They are attacking your soul. They are killing anything that could inspire your resistance. It is done on purpose. Beware.",a:"Salvatore Brizzi"}},
{it:{t:"Per quanto è possibile, tramite la conoscenza, la fede, la speranza e l'amore, si deve aiutare la vita a mantenersi. Non bisogna permettere alle forze negative di riportare la vittoria.",a:"Omraam Mikhaël Aïvanhov"},
 en:{t:"As far as possible, through knowledge, faith, hope and love, one must help life sustain itself. One must not allow negative forces to carry the victory.",a:"Omraam Mikhaël Aïvanhov"}},
{it:{t:"Tutto lo spirito che non si radica nella materia è volatile ed effimero. Il corpo è l'unico vero tempio dello Spirito. Diamoci da fare, alziamoci le maniche e affrettiamoci lentamente, con i piedi ben radicati a terra.",a:"Sapienza della tradizione"},
 en:{t:"All spirit that does not root itself in matter is volatile and ephemeral. The body is the only true temple of the Spirit. Let us get to work, roll up our sleeves and hasten slowly, with our feet firmly rooted in the ground.",a:"Wisdom of the tradition"}},
{it:{t:"La verità è come un leone. Non avrai bisogno di difenderla. Lasciala libera. Si difenderà da sola.",a:"Sant'Agostino"},
 en:{t:"Truth is like a lion. You will not need to defend it. Set it free. It will defend itself.",a:"St Augustine"}},
{it:{t:"Dico e attesto che il Nostro Potere è diverso. Il Nostro Potere è sacrificio.",a:"Foglie del Giardino di Morya, Appello 1924"},
 en:{t:"I say and attest that Our Power is different. Our Power is sacrifice.",a:"Leaves of Morya's Garden, The Call 1924"}},
{it:{t:"La vita reale inizia quando 'Io ci sono' e sono 'Presente a me stesso'. Solo allora posso iniziare a creare un futuro che non sia solo un copia-incolla del mio passato.",a:"Roberto Potocniak"},
 en:{t:"Real life begins when 'I am here' and 'I am present to myself.' Only then can I begin to create a future that is not just a copy-paste of my past.",a:"Roberto Potocniak"}},
{it:{t:"C'è un unico fondamentale requisito perché una relazione sentimentale possa sopravvivere a sé stessa: la presenza di un contenitore più grande, comune ad entrambi. Due 'iniziati' che vivono ogni giornata con la gioia di una nuova scoperta hanno un territorio comune di qualità elevatissima.",a:"Antonio Esposito"},
 en:{t:"There is one fundamental requirement for a romantic relationship to survive itself: the presence of a larger container, common to both. Two 'initiates' who live each day with the joy of a new discovery share a territory of the highest quality.",a:"Antonio Esposito"}},
{it:{t:"Il ricordo di sé è uno stato di meraviglia, nel quale la mente tace. Ti commuovi perché sei vivo, non perché ti è successo qualcosa di particolare. Finalmente, ti senti vivo.",a:"Salvatore Brizzi"},
 en:{t:"Self-remembering is a state of wonder, in which the mind falls silent. You are moved because you are alive, not because something particular has happened. At last, you feel alive.",a:"Salvatore Brizzi"}},
{it:{t:"Il femminino sacro è la capacità dell'essere umano, nella sua ascesa al Padre, di creare e portare frutti nella materia venendo direttamente fecondato da Dio senza interferenza umana. Sarà questo il femminino sacro che dovremo incarnare.",a:"Anna Carla Digregorio"},
 en:{t:"The sacred feminine is the capacity of the human being, in their ascent to the Father, to create and bear fruit in matter while being directly fertilised by God without human interference. This is the sacred feminine we shall have to embody.",a:"Anna Carla Digregorio"}},
{it:{t:"L'Intelligenza cosmica non comincia mai dalla sofferenza, ma ricorre a quest'ultima solo dopo aver provato di tutto per far riflettere gli umani.",a:"Omraam Mikhaël Aïvanhov"},
 en:{t:"Cosmic Intelligence never begins with suffering, but resorts to it only after having tried everything to make humans reflect.",a:"Omraam Mikhaël Aïvanhov"}},
{it:{t:"Non incolpare mai, non lamentarti mai di nessuno, di niente. Il trionfo del vero uomo proviene dalle ceneri del suo errore. Guarda te stesso allo specchio, sarai libero e forte, perché tu stesso sei il tuo destino.",a:"Pablo Neruda"},
 en:{t:"Never blame, never complain about anyone or anything. The triumph of the true man comes from the ashes of his error. Look at yourself in the mirror, you will be free and strong, for you yourself are your destiny.",a:"Pablo Neruda"}},
{it:{t:"Non è il male che sta aumentando: sta aumentando la luce. Immagini di aver immagazzinato per anni i suoi oggetti in una stanza illuminata da una lampadina da 40 watt. Cambi quella lampadina con una da 100 watt e vedrà cosa accade! Lo sporco sarà evidente.",a:"Sai Baba"},
 en:{t:"It is not that evil is increasing: the light is increasing. Imagine having stored your belongings for years in a room lit by a 40-watt bulb. Switch it for a 100-watt one and see what happens! The dirt becomes evident.",a:"Sai Baba"}},
{it:{t:"Quando risparmi qualcuno, quando lo approvi nei suoi peccati, quando non condividi con lui la Verità, allora non lo ami. Il vero amore si mette in gioco, soffre per l'altro, agisce. Fino alla fine di tutto.",a:"Padre Costantino Sturzu"},
 en:{t:"When you spare someone, when you approve of their sins, when you do not share the Truth with them, then you do not love them. True love puts itself on the line, suffers for the other, acts. To the very end.",a:"Father Constantino Sturzu"}},
{it:{t:"Sii te stesso in ogni situazione. Nessuna tempesta ha il potere di sradicare le tue radici, se tu non vuoi. Ascolta l'intuito. Solo tu conosci la tua Verità.",a:"Insegnamento spirituale"},
 en:{t:"Be yourself in every situation. No storm has the power to uproot you, if you do not wish it. Listen to intuition. Only you know your Truth.",a:"Spiritual teaching"}},
{it:{t:"Il vero scopo della coppia non è tanto 'stare insieme' ma 'creare insieme'. Una coppia che non crea va contro l'impulso dell'Universo. In una coppia si è in 3: tu, io e la relazione. Il mio spazio interiore è sacro, sacro come il tuo.",a:"Nicolas Tamayo"},
 en:{t:"The true purpose of a couple is not so much to 'be together' but to 'create together.' A couple that does not create goes against the impulse of the Universe. In a couple there are 3: you, me and the relationship. My inner space is sacred, sacred like yours.",a:"Nicolas Tamayo"}},
{it:{t:"I demoni vanno abbracciati, in quel momento ti apriranno le porte della rinascita. I demoni sono come i draghi, vanno baciati, non vanno uccisi.",a:"Bride An Geal"},
 en:{t:"Demons must be embraced; in that moment they will open the doors of rebirth. Demons are like dragons, they must be kissed, not killed.",a:"Bride An Geal"}},
{it:{t:"La natura superiore vi dice: invece di rimuginare e di cercare la vendetta, cerca piuttosto di utilizzare e trasformare quell'offesa. Tu sei un alchimista, ricaverai dell'oro.",a:"Omraam Mikhaël Aïvanhov"},
 en:{t:"The higher nature tells you: instead of brooding and seeking revenge, try instead to use and transform that offence. You are an alchemist, you will draw gold from it.",a:"Omraam Mikhaël Aïvanhov"}},
{it:{t:"L'origine della guerra è nel sonno del genere umano. Per cavarvela nei prossimi anni dovete svegliarvi e 'uscire dal genere umano'.",a:"Georges I. Gurdjieff, via Salvatore Brizzi"},
 en:{t:"The origin of war lies in the sleep of the human race. To get through the coming years you must wake up and 'leave the human race.'",a:"Georges I. Gurdjieff, via Salvatore Brizzi"}},
{it:{t:"L'angolo più oscuro dell'inferno è riservato a coloro che mantengono la loro neutralità in momenti di crisi morale.",a:"Dante Alighieri, La Divina Commedia"},
 en:{t:"The darkest corner of hell is reserved for those who maintain their neutrality in times of moral crisis.",a:"Dante Alighieri, The Divine Comedy"}},
{it:{t:"Il pittore, lo scienziato, l'uomo curioso: tutti coloro che osservano il mondo con attenzione scoprono dettagli che sfuggono agli altri. È nella capacità di meravigliarsi e di interrogarsi continuamente che nasce la vera conoscenza.",a:"Leonardo Da Vinci"},
 en:{t:"The painter, the scientist, the curious one: all who observe the world attentively discover details that escape others. It is in the capacity to wonder and to question ceaselessly that true knowledge is born.",a:"Leonardo Da Vinci"}},
{it:{t:"Chi si conosce, non si lascia turbare dagli eventi.",a:"Seneca"},
 en:{t:"Those who know themselves are not disturbed by events.",a:"Seneca"}},
{it:{t:"Che accadrebbe se, un giorno o una notte, un demone ti dicesse: questa vita dovrai viverla ancora innumerevoli volte, e non ci sarà in essa mai niente di nuovo?",a:"Friedrich Nietzsche, L'eterno ritorno"},
 en:{t:"What would happen if, one day or one night, a demon told you: this life you must live once more and innumerable times more, and there will never be anything new in it?",a:"Friedrich Nietzsche, The Eternal Return"}},
{it:{t:"La verità era uno specchio che cadendo dal cielo si ruppe. Ciascuno ne prese un pezzo e vedendo riflessa in esso la propria immagine, credette di possedere l'intera verità.",a:"Jalāl al-Dīn Rūmī"},
 en:{t:"The truth was a mirror that, falling from heaven, shattered. Everyone took a piece and, seeing their own image reflected in it, believed they possessed the entire truth.",a:"Jalāl al-Dīn Rūmī"}},
{it:{t:"Una volta per tutte ti viene imposto un breve precetto: ama e fa ciò che vuoi. Sia che tu taccia, taci per amore. Sia che tu parli, parla per amore. Sia in te la radice dell'amore, poiché da questa radice non può procedere se non il bene.",a:"Sant'Agostino"},
 en:{t:"Once and for all, a short precept is laid upon you: love and do what you will. Whether you keep silent, keep silent out of love. Whether you speak, speak out of love. Let the root of love be within you, for from this root nothing but good can spring.",a:"St Augustine"}},
{it:{t:"Non va piantato un albero il giorno in cui vuoi l'ombra.",a:"Proverbio Zen"},
 en:{t:"Do not plant a tree on the day you want shade.",a:"Zen proverb"}},
{it:{t:"Tutto quello che stai attraversando, ti sta preparando a ciò che hai chiesto.",a:"Eckhart Tolle"},
 en:{t:"Everything you are going through is preparing you for what you asked for.",a:"Eckhart Tolle"}},
{it:{t:"Dio dorme nelle pietre, sogna nelle piante, si risveglia nell'animale e diventa cosciente nell'essere umano.",a:"Antico aforisma"},
 en:{t:"God sleeps in stones, dreams in plants, awakens in animals and becomes conscious in the human being.",a:"Ancient aphorism"}},
{it:{t:"Se l'uomo non è capace di governare le proprie emozioni e le proprie pulsioni, non sarà mai in grado di dominare se stesso.",a:"Cicerone"},
 en:{t:"If a man is not capable of governing his own emotions and impulses, he will never be able to master himself.",a:"Cicero"}},
{it:{t:"Per mezzo della Temperanza l'uomo diventa saggio, e soltanto il saggio può sperimentare il piacere autentico, ed è questo che lo renderà differente da un animale.",a:"Aristotele"},
 en:{t:"Through Temperance man becomes wise, and only the wise can experience authentic pleasure, and this is what will make him different from an animal.",a:"Aristotle"}},
{it:{t:"Nella bottega di Dio non si vendono i frutti maturi, ma i piccoli semi da coltivare. Vai nel mondo e fai germogliare i doni che Dio ti ha donato.",a:"Parabola della bottega dei doni di Dio"},
 en:{t:"In God's shop, ripe fruits are not sold, but small seeds to cultivate. Go into the world and make the gifts God gave you flourish.",a:"Parable of God's gift shop"}},
{it:{t:"La geometria è musica solidificata.",a:"Pitagora"},
 en:{t:"Geometry is solidified music.",a:"Pythagoras"}},
{it:{t:"La via non è nel cielo: la via si trova nel cuore.",a:"Buddha"},
 en:{t:"The way is not in the sky: the way is in the heart.",a:"Buddha"}},
{it:{t:"Per questo vi dico: tutte le cose che chiedete in preghiera, abbiate fede di averle già ricevute e le avrete.",a:"Marco 11:24"},
 en:{t:"Therefore I say to you: whatever things you ask in prayer, believe that you have already received them and you shall have them.",a:"Mark 11:24"}},
{it:{t:"I due giorni più importanti della vita sono quello in cui sei nato e quello in cui capisci perché.",a:"Mark Twain"},
 en:{t:"The two most important days in your life are the day you are born and the day you find out why.",a:"Mark Twain"}},
{it:{t:"Io sono venuto nel mondo come luce, perché chiunque crede in me non rimanga nelle tenebre.",a:"Giovanni 12,46"},
 en:{t:"I have come into the world as a light, so that whoever believes in me should not remain in darkness.",a:"John 12:46"}},
{it:{t:"Nessuno ha un amore più grande di questo: dare la sua vita per i propri amici.",a:"Giovanni 15,13"},
 en:{t:"No one has greater love than this: to lay down one's life for one's friends.",a:"John 15:13"}},
{it:{t:"L'idea di servire Dio ha un senso solo se l'essere umano prende coscienza che la divinità che egli deve servire dimora nella propria anima.",a:"Omraam Mikhaël Aïvanhov"},
 en:{t:"The idea of serving God has meaning only if the human being becomes aware that the divinity they must serve dwells within their own soul.",a:"Omraam Mikhaël Aïvanhov"}},
{it:{t:"Tu non hai una vita, tu sei la vita. L'unica vita, l'unica consapevolezza assume la forma di un uomo o di una donna, un filo d'erba, un cane, un pianeta, il sole, una galassia. Questo è il gioco delle forme, la danza della vita.",a:"Eckhart Tolle"},
 en:{t:"You do not have a life, you are life. The one life, the one consciousness takes the form of a man or a woman, a blade of grass, a dog, a planet, the sun, a galaxy. This is the play of forms, the dance of life.",a:"Eckhart Tolle"}},
{it:{t:"Il vero amore è fatto di gentilezza amorevole, di capacità di offrire felicità agli altri, di compassione, di gioia condivisa e di libertà per l'uno e per l'altro.",a:"Thich Nhat Hanh"},
 en:{t:"True love is made of loving kindness, of the ability to offer happiness to others, of compassion, of shared joy and of freedom for one and the other.",a:"Thich Nhat Hanh"}},
{it:{t:"Ti lodo, Padre, Signore del cielo e della terra, perché hai nascosto queste cose ai sapienti e ai dotti e le hai rivelate ai piccoli.",a:"Matteo 11:25"},
 en:{t:"I praise you, Father, Lord of heaven and earth, because you have hidden these things from the wise and learned and revealed them to little children.",a:"Matthew 11:25"}},
{it:{t:"Ricerca il vuoto ed il silenzio con tutto il tuo essere, quell'essere stesso fatto di vuoto e silenzio. Ricercandoli ti ritroverai, e ritrovandoti diverrai ciò che cerchi.",a:"Meditazione della Scuola ContattaTi"},
 en:{t:"Seek emptiness and silence with all your being, that very being made of emptiness and silence. In seeking them you will find yourself, and in finding yourself you will become what you seek.",a:"Meditation of Scuola ContattaTi"}},
{it:{t:"Una vita senza ricerca non è degna per l'uomo di essere vissuta.",a:"Socrate"},
 en:{t:"An unexamined life is not worth living for a human being.",a:"Socrates"}},
{it:{t:"Di tutto il creato, l'uomo è l'unico essere duplice: mortale secondo la sua corporeità, immortale secondo la sua essenza.",a:"Ermete Trismegisto"},
 en:{t:"Of all creation, man is the only dual being: mortal according to his corporeal nature, immortal according to his essence.",a:"Hermes Trismegistus"}},
{it:{t:"Tu ora sei quell'anima che in questa terra puoi ricongiungere ciò che viene visto come separato. Tu ora sei quell'anima che attraverso l'amore puoi tornare ad essere quella luce che annulla l'oscurità.",a:"Meditazione della Scuola ContattaTi"},
 en:{t:"You are now that soul which in this earth can reunite what is seen as separate. You are now that soul which through love can return to being that light which annuls the darkness.",a:"Meditation of Scuola ContattaTi"}},
{it:{t:"Tu non sei quella ferita, sei solo identificato con la sua maschera. Lascia andare quell'identificazione e la ferita svanirà.",a:"Meditazione della Scuola ContattaTi"},
 en:{t:"You are not that wound, you are merely identified with its mask. Let go of that identification and the wound will vanish.",a:"Meditation of Scuola ContattaTi"}},
{it:{t:"La conoscenza è Magia ed è la sola Legge. Non abbiate paura del potere dentro di voi, poiché esso segue la Legge come le stelle nel cielo. Segui e impara la mia Magia. Sappi che tutta la Forza è tua, se lo vorrai.",a:"Toth l'Atlantideo, Tavole di Smeraldo"},
 en:{t:"Knowledge is Magic and is the only Law. Do not be afraid of the power within you, for it follows the Law as the stars in the sky. Follow and learn my Magic. Know that all the Force is yours, if you will it.",a:"Thoth the Atlantean, Emerald Tablets"}},
{it:{t:"Non cercare il mondo in te stesso, ma trova te stesso nel mondo.",a:"Antico proverbio egizio"},
 en:{t:"Do not seek the world in yourself, but find yourself in the world.",a:"Ancient Egyptian proverb"}},
{it:{t:"Non portare il mondo nel rito: porta il rito nel mondo.",a:"Massima iniziatica"},
 en:{t:"Do not bring the world into the rite: bring the rite into the world.",a:"Initiatic maxim"}},
{it:{t:"Il tempo non guarisce; la presenza sì.",a:"Massima iniziatica"},
 en:{t:"Time does not heal; presence does.",a:"Initiatic maxim"}},
{it:{t:"I demoni interiori non sono nemici, ma parti rimaste sospese. Quando li vediamo senza paura, quando li ascoltiamo senza giudizio, la loro forma cambia. Ciò che sembrava ombra rivela la sua origine.",a:"Meditazione della Scuola ContattaTi"},
 en:{t:"Inner demons are not enemies, but parts left in suspension. When we see them without fear, when we listen to them without judgement, their form changes. What seemed shadow reveals its origin.",a:"Meditation of Scuola ContattaTi"}},
{it:{t:"Il genio è colui che è a suo agio nel disagio.",a:"Joe Dispenza"},
 en:{t:"Genius is one who is at ease in discomfort.",a:"Joe Dispenza"}},
{it:{t:"Quando incontri qualcuno ricordati che è un incontro sacro. Come lo vedi ti vedi, come lo tratti ti tratti, come lo pensi ti pensi.",a:"Meditazione della Scuola ContattaTi"},
 en:{t:"When you meet someone, remember that it is a sacred encounter. How you see them, you see yourself; how you treat them, you treat yourself; how you think of them, you think of yourself.",a:"Meditation of Scuola ContattaTi"}},
{it:{t:"Scopri chi sei e non avere paura di realizzarlo.",a:"Mahatma Gandhi"},
 en:{t:"Find out who you are and do not be afraid to be it.",a:"Mahatma Gandhi"}},
{it:{t:"L'amicizia è sempre una dolce responsabilità, mai un'opportunità.",a:"Khalil Gibran"},
 en:{t:"Friendship is always a sweet responsibility, never an opportunity.",a:"Khalil Gibran"}},
{it:{t:"Nella mente nasce la sofferenza. Nella mente può essere risolta.",a:"Buddha"},
 en:{t:"In the mind suffering is born. In the mind it can be resolved.",a:"Buddha"}},
{it:{t:"La verità non è qualcosa da conoscere. È qualcosa da ricordare.",a:"Scuola ContattaTi"},
 en:{t:"Truth is not something to be known. It is something to be remembered.",a:"Scuola ContattaTi"}},
{it:{t:"Mi raccomando a morire vivi.",a:"Georges Ivanovitch Gurdjieff"},
 en:{t:"I urge you to die alive.",a:"Georges Ivanovitch Gurdjieff"}},
{it:{t:"Sei divino, non dimenticarlo mai. Siamo tutti uno, in eterno contatto con l'anima unica.",a:"Giordano Bruno"},
 en:{t:"You are divine, never forget it. We are all one, in eternal contact with the single soul.",a:"Giordano Bruno"}},
{it:{t:"La gratitudine è la memoria del cuore.",a:"Lao Tzu"},
 en:{t:"Gratitude is the memory of the heart.",a:"Lao Tzu"}},
{it:{t:"Il segreto dell'evoluzione non è diventare qualcuno che non siamo, bensì tirar fuori ciò che siamo realmente.",a:"Ermete Trismegisto"},
 en:{t:"The secret of evolution is not becoming someone we are not, but bringing forth what we truly are.",a:"Hermes Trismegistus"}},
{it:{t:"Quanto più a fondo scava il dolore nel nostro cuore, tanta più gioia potremo contenere.",a:"Kahlil Gibran"},
 en:{t:"The deeper that sorrow carves into your being, the more joy you can contain.",a:"Kahlil Gibran"}},
{it:{t:"Chi non è pronto a morire non è pronto per la libertà. Di fronte alla morte la Fiamma del Cuore arde con la massima intensità.",a:"Draco Daatson, Guerrieri Metropolitani"},
 en:{t:"Whoever is not ready to die is not ready for freedom. In the face of death the Flame of the Heart burns with the greatest intensity.",a:"Draco Daatson, Metropolitan Warriors"}},
{it:{t:"Quando sei in uno stato di gratitudine sei in uno stato di ricezione.",a:"Joe Dispenza"},
 en:{t:"When you are in a state of gratitude, you are in a state of receivership.",a:"Joe Dispenza"}},
{it:{t:"Non si nasce nel momento in cui si entra in questa dimensione, si nasce nel momento in cui si prende in mano la propria vita.",a:"Eduardo Muscarà"},
 en:{t:"We are not born the moment we enter this dimension; we are born the moment we take our life into our own hands.",a:"Eduardo Muscarà"}},
{it:{t:"La natura parla un linguaggio che non è quello che vediamo ma quello che possiamo sentire; secondo me i gelsomini parlano attraverso il profumo. L'apertura della rosa l'ho sempre vista come un insegnamento: senti che lo fa per te che la stai guardando, perché non ha altro scopo.",a:"Franco Battiato"},
 en:{t:"Nature speaks a language that is not what we see but what we can feel; to me, jasmine speaks through its scent. I have always seen the opening of a rose as a teaching: you feel it does so for you who are watching, because it has no other purpose.",a:"Franco Battiato"}},
{it:{t:"Io sono il mare: non sono una goccia che si perde nel mare, ma sono il mare che si riconosce nella goccia. Tutti i fiumi trovano una via per giungere al mare, perché si riconoscono in lui trovando se stessi. Quello che sappiamo è una goccia, quello che non sappiamo è un oceano. Sii il mare, mia piccola grande Anima.",a:"Nicolaos Anifantis"},
 en:{t:"I am the sea: I am not a drop lost in the sea, I am the sea that recognises itself in the drop. All rivers find a way to reach the sea, because they recognise themselves in it and so find themselves. What we know is a drop, what we do not know is an ocean. Be the sea, my little great Soul.",a:"Nicolaos Anifantis"}},
{it:{t:"Cercare Dio è la fede, trovarlo è la speranza, conoscerlo è l'amore, sentirlo è la pace, gustarlo è la gioia, possederlo è l'estasi.",a:"Marthe Robin"},
 en:{t:"To seek God is faith, to find him is hope, to know him is love, to feel him is peace, to taste him is joy, to possess him is ecstasy.",a:"Marthe Robin"}},
{it:{t:"S'inganna colui che crede di potersi sottrarre ai risultati dell'azione con l'astenersi da questa e col restare inoperoso. Nell'universo non esiste affatto l'inazione, poiché tutto vi è in costante attività e nulla può sfuggire alla legge generale.",a:"Bhagavad Gita"},
 en:{t:"Deceived is he who believes he can escape the results of action by abstaining from it and remaining idle. In the universe there is no such thing as inaction, for everything in it is in constant activity and nothing can escape the general law.",a:"Bhagavad Gita"}},
{it:{t:"Incongruenze e incoerenze sono alla base dell'addormentamento. Si può essere incoerenti solo se non si è nel cuore, e si può essere incongruenti solo se non si è fedeli al proprio scopo di vita. Solo una è la strada che porta al Sole.",a:"Anna Carla Digregorio"},
 en:{t:"Incongruences and inconsistencies lie at the root of our sleep. One can be inconsistent only when not in the heart, and incongruent only when unfaithful to one's life purpose. Only one road leads to the Sun.",a:"Anna Carla Digregorio"}},
{it:{t:"Siamo gocce d'acqua che evaporano ancor prima di toccare il suolo, tutte le volte che lottiamo per un ideale e ci scontriamo con qualcosa di apparentemente più grande di noi. Ma tutte quelle gocce, risalendo in alto, si riconoscono le une con le altre e unendosi divengono tempesta.",a:"Nicolaos Anifantis"},
 en:{t:"We are drops of water that evaporate before even touching the ground, every time we fight for an ideal and collide with something seemingly greater than us. But all those drops, rising up again, recognise one another and, uniting, become a storm.",a:"Nicolaos Anifantis"}},
{it:{t:"Quando ti definisci in base a un credo, una cultura, una nazionalità, una tradizione, questa azione traspira violenza: perché ti stai separando dal resto dell'umanità. Chi cerca di comprendere la violenza non dovrebbe appartenere a nessuna nazione, religione o schieramento; dovrebbe comprendere che è parte del totale dell'umanità.",a:"J. Krishnamurti"},
 en:{t:"When you define yourself by a creed, a culture, a nationality, a tradition, that very act breathes violence: because you are separating yourself from the rest of humanity. Whoever seeks to understand violence should belong to no nation, religion or faction; they should understand that they are part of the whole of humanity.",a:"J. Krishnamurti"}},
{it:{t:"Quello che siete oggi è il risultato delle vostre decisioni e scelte passate. Quello che sarete domani sarà il risultato delle vostre azioni di oggi.",a:"Swami Vivekananda"},
 en:{t:"What you are today is the result of your past decisions and choices. What you will be tomorrow will be the result of your actions today.",a:"Swami Vivekananda"}},
{it:{t:"Cominciate a fare ciò che è necessario, poi ciò che è possibile, e all'improvviso vi sorprenderete a fare l'impossibile.",a:"San Francesco d'Assisi"},
 en:{t:"Start by doing what is necessary, then what is possible, and suddenly you will find yourself doing the impossible.",a:"Saint Francis of Assisi"}},
{it:{t:"Non credere che tu possa apparir santo se nessuno ti metterà alla prova. Santo lo sei quando non ti turbi di fronte agli insulti, quando ti addolori per chi te li arreca, quando non ti preoccupi per ciò che soffri ma ti rammarichi per colui che ti fa soffrire. Tutto in questo è misericordia.",a:"Sant'Agostino"},
 en:{t:"Do not believe you can appear holy if no one puts you to the test. You are holy when you are not troubled by insults, when you grieve for the one who inflicts them, when you do not worry about what you suffer but feel sorrow for the one who makes you suffer. In all this lies mercy.",a:"St Augustine"}},
{it:{t:"E noi tutti, a viso scoperto, riflettendo come in uno specchio la gloria del Signore, veniamo trasformati in quella medesima immagine, di gloria in gloria.",a:"2ª Lettera ai Corinzi"},
 en:{t:"And we all, with unveiled faces, reflecting as in a mirror the glory of the Lord, are being transformed into that same image, from glory to glory.",a:"2nd Letter to the Corinthians"}},
{it:{t:"Chi sono io? Sono un'esperienza! Sta a te decidere fino a che punto e a che profondità viverla.",a:"Nicolaos Anifantis"},
 en:{t:"Who am I? I am an experience! It is up to you to decide how far and how deeply to live it.",a:"Nicolaos Anifantis"}},
{it:{t:"Non siamo il nostro corpo fisico mortale, quello appartiene alla materia: cenere alla cenere e polvere alla polvere. Ma siamo Anima immortale, e quell'Anima è l'essenza di tutto il visibile finito e dell'invisibile infinito.",a:"Nicolaos Anifantis"},
 en:{t:"We are not our mortal physical body, that belongs to matter: ashes to ashes and dust to dust. But we are immortal Soul, and that Soul is the essence of all the finite visible and the infinite invisible.",a:"Nicolaos Anifantis"}},
{it:{t:"Una madre ed un padre hanno un unico dovere nei confronti dei propri figli: non spegnere la luce nei loro occhi. Quella gioia che sprizza dal loro interno va tutelata e protetta ad ogni costo. Chiediamoci: in che modo, attraverso le mie azioni, decisioni o parole, sto affievolendo quella luce?",a:"Nicolaos Anifantis"},
 en:{t:"A mother and a father have one single duty towards their children: not to put out the light in their eyes. That joy which springs from within them must be safeguarded and protected at all costs. Let us ask ourselves: in what way, through my actions, decisions or words, am I dimming that light?",a:"Nicolaos Anifantis"}},
{it:{t:"Non siete venuti qui per combattere l'ombra: siete venuti per accorgervi attraverso di essa che voi siete luce. Non siete venuti per evitare il dolore, ma per farne esperienza e trascenderlo. Più evitate parti di voi, più allontanate il ritorno a casa.",a:"Monica Grando"},
 en:{t:"You did not come here to fight the shadow: you came to realise through it that you are light. You did not come to avoid pain, but to experience it and transcend it. The more you avoid parts of yourself, the further you push away the return home.",a:"Monica Grando"}},
{it:{t:"L'uomo non è un essere ma un processo, non un essere ma un divenire. Il cane nasce e muore cane: la situazione non è necessariamente la stessa per quanto riguarda l'uomo. L'uomo può nascere uomo e morire come Gautama il Buddha.",a:"Osho"},
 en:{t:"Man is not a being but a process, not a being but a becoming. A dog is born a dog and dies a dog: the situation is not necessarily the same for man. Man can be born a man and die as Gautama the Buddha.",a:"Osho"}},
{it:{t:"Essere se stessi in un mondo che cerca continuamente di uniformarti è la più grande delle conquiste.",a:"Ralph Waldo Emerson"},
 en:{t:"To be yourself in a world that is constantly trying to make you something else is the greatest accomplishment.",a:"Ralph Waldo Emerson"}}
];
